-- Staging survey definitions captured on 2026-09-20. No participant responses.
-- Preserve the original author IDs; that author exists in production.
-- Existing definitions are preserved if an ID is already present.

on conflict (id) do nothing;

select setval('public.demographic_questions_id_seq', greatest(
  coalesce((select max(id) from public.demographic_questions), 1),
  coalesce(pg_sequence_last_value('public.demographic_questions_id_seq'::regclass), 1)
));

on conflict (id) do nothing;

select setval('public.demographic_answers_id_seq', greatest(
  coalesce((select max(id) from public.demographic_answers), 1),
  coalesce(pg_sequence_last_value('public.demographic_answers_id_seq'::regclass), 1)
));

on conflict (id) do nothing;

select setval('public.demographic_answer_question_mapping_id_seq', greatest(
  coalesce((select max(id) from public.demographic_answer_question_mapping), 1),
  coalesce(pg_sequence_last_value('public.demographic_answer_question_mapping_id_seq'::regclass), 1)
));
